// Type of seed.json (generated by npm run gen, about 25 MB). With allowArbitraryExtensions (tsconfig.json), TypeScript reads this
// declaration instead of inferring a literal type from the JSON itself, which cost about a minute and a gigabyte of every tsc run
// (TECH-02, 2026-10-17). Vite still bundles the real file; callers cast to their own row shapes as before.
type SeedRow = Record<string, any>;
declare const seed: {
  meta: { generated_at: string; digest?: string; demo_today: string };
  personas: { persona: string; person_id: string; nexus: boolean; [k: string]: unknown }[];
  tables: Record<string, SeedRow[]>;
};
export default seed;
